import re

UNITS = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
PIECE = re.compile(r'(\d+)\s*([dhms])')

def parse_duration(text):
    total = 0
    pos = 0
    for match in PIECE.finditer(text):
        if text[pos:match.start()].strip():
            raise ValueError(f'unexpected text: {text[pos:match.start()]!r}')
        total += int(match.group(1)) * UNITS[match.group(2)]
        pos = match.end()
    if pos == 0 or text[pos:].strip():
        raise ValueError(f'not a duration: {text!r}')
    return total

for sample in ['45s', '90m', '1h30m', '2d', '1h15m10s', 'soon', '1x']:
    try:
        print(sample, '->', parse_duration(sample))
    except ValueError as e:
        print(sample, '-> ERROR:', e)

