def lex(text):
    pairs = []
    i, n = 0, len(text)
    while i < n:
        while i < n and text[i] == ' ':
            i += 1
        if i >= n:
            break
        start = i
        while i < n and text[i] != '=':
            i += 1
        key = text[start:i]
        i += 1  # skip =
        if i < n and text[i] == '"':
            i += 1
            start = i
            while i < n and text[i] != '"':
                i += 1
            value = text[start:i]
            i += 1  # skip closing quote
        else:
            start = i
            while i < n and text[i] != ' ':
                i += 1
            value = text[start:i]
        pairs.append((key, value))
    return pairs

