def tokenize(expr):
    tokens = []
    i, n = 0, len(expr)
    while i < n:
        ch = expr[i]
        if ch == ' ':
            i += 1
        elif ch.isdigit():
            start = i
            while i < n and expr[i].isdigit():
                i += 1
            tokens.append(int(expr[start:i]))
        elif ch in '+-*/()':
            tokens.append(ch)
            i += 1
        else:
            raise ValueError(f'unexpected character {ch!r} at position {i}')
    return tokens

