def check_username(name):
    failures = []
    if not name:
        return ['must not be empty']
    if not (3 <= len(name) <= 16):
        failures.append('length must be 3-16 characters')
    if not name[0].isalpha():
        failures.append('must start with a letter')
    if not all(c.isalnum() or c == '_' for c in name):
        failures.append('only letters, digits, and underscores allowed')
    return failures

for candidate in ['ana_ruiz', 'ab', '9lives', 'bad name', '']:
    print(repr(candidate), '->', check_username(candidate))

def check_email(addr):
    failures = []
    addr = addr.strip()
    if addr.count('@') != 1:
        return ['must contain exactly one @']
    local, domain = addr.split('@')
    if not local:
        failures.append('nothing before the @')
    if any(c.isspace() for c in addr):
        failures.append('contains spaces')
    if '.' not in domain:
        failures.append('domain has no dot')
    if domain.startswith('.') or domain.endswith('.'):
        failures.append('domain starts or ends with a dot')
    if len(domain.rsplit('.', 1)[-1]) < 2:
        failures.append('top-level domain too short')
    return failures

for a in ['ana@example.com', 'ana@example', 'ana@@x.com', '@x.com', 'ana @x.com', 'ana@x.c']:
    print(a, '->', check_email(a))

def check_password(pw):
    failures = []
    if len(pw) < 10:
        failures.append('at least 10 characters')
    if not any(c.isupper() for c in pw):
        failures.append('needs an uppercase letter')
    if not any(c.islower() for c in pw):
        failures.append('needs a lowercase letter')
    if not any(c.isdigit() for c in pw):
        failures.append('needs a digit')
    if not any(not c.isalnum() for c in pw):
        failures.append('needs a symbol')
    return failures

for pw in ['abc', 'longpassword', 'Str0ng!pass']:
    print(repr(pw), '->', check_password(pw))

